{"implementation": "def solve(case):
    threshold = case['threshold']
    calls = case['calls']
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        call_id = call['call_id']
        gain = call['loss_without_call'] - call['loss_with_call']
        norm_gain = gain / call['prediction_tokens']
        norm_gain_rounded = round(norm_gain, 6)
        accepted = call['parseable'] and norm_gain_rounded >= threshold
        diagnostics.append({
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': norm_gain_rounded
        })
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
